const cur = (path, p) => (path === p ? ' aria-current="page"' : "");
const inSection = (path, item) => path === item.path || path.startsWith(item.path + "/") || (item.children || []).some((c) => c.path === path);

function header(path) {
  const nav = NAV.map((item) => {
    if (!item.children) return `<a href="${href(item.path)}"${cur(path, item.path) || (path.startsWith(item.path + "/") ? ' aria-current="page"' : "")}>${esc(item.label)}</a>`;
    return `<div class="dd"><button class="dd-btn${inSection(path, item) ? " is-current" : ""}" type="button" aria-expanded="false" aria-controls="dd-trainers">${esc(item.label)}${icon("chevron")}</button>
<div class="dd-panel" id="dd-trainers">${item.children.map((c) => `<a href="${href(c.path)}"${cur(path, c.path)}>${esc(c.label)}</a>`).join("")}<hr><a href="${href(item.path)}"${cur(path, item.path)}>All specialties ${icon("arrow")}</a></div></div>`;
  }).join("");
  return `<header class="site-header">
<div class="container hdr">
  <a class="hdr-logo" href="index.html" aria-label="trainsyou home"><img src="assets/trainsyou-lockup-ink.svg" width="162" height="41" alt="trainsyou"></a>
  <nav class="hdr-nav" aria-label="Main">${nav}</nav>
  <div class="hdr-actions">
    <a class="hdr-signin" href="login.html"${cur(path, "/login")}>Sign in</a>
    ${primaryCta({ location: "header", size: "sm" })}
    <button class="menu-btn" type="button" aria-expanded="false" aria-controls="sheet" aria-label="Open menu"><span class="menu-label">Menu</span><svg viewBox="0 0 18 18" fill="none" aria-hidden="true"><path class="bar bar-1" d="M2 5h14" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/><path class="bar bar-2" d="M2 13h14" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/></svg></button>
  </div>
</div>
</header>
<div class="sheet" id="sheet" role="dialog" aria-modal="true" aria-label="Menu">
<div class="sheet-inner">
  <ul class="sheet-list">${NAV.filter((n) => !n.children).map((n) => `<li><a href="${href(n.path)}"${cur(path, n.path)}>${esc(n.label)}${icon("arrow")}</a></li>`).join("")}</ul>
  ${NAV.filter((n) => n.children).map((n) => `<div class="sheet-group"><p class="eyebrow eyebrow--muted">${esc(n.label)}</p><ul class="sheet-list sheet-sub">${n.children.map((c) => `<li><a href="${href(c.path)}"${cur(path, c.path)}>${esc(c.label)}</a></li>`).join("")}<li><a href="${href(n.path)}"${cur(path, n.path)}>All specialties</a></li></ul></div>`).join("")}
  <div class="sheet-group"><p class="eyebrow eyebrow--muted">More</p><ul class="sheet-list sheet-sub">${MORE.map((c) => `<li><a href="${href(c.path)}"${cur(path, c.path)}>${esc(c.label)}</a></li>`).join("")}</ul>
  <div class="sheet-foot"><a class="btn btn--secondary" href="login.html">Sign in</a></div></div>
</div>
</div>`;
}

function footer() {
  const cols = content.footer.map((g) => ({ ...g, links: g.links.filter((l) => l.href !== "/coaches") }));
  return `<footer class="site-footer">
<div class="container">
  <div class="foot-top">
    <div class="foot-brand"><img src="assets/trainsyou-lockup-ink.svg" width="142" height="36" alt="trainsyou"><p>${esc(content.brand.copy.line)} ${esc(content.brand.copy.descriptor)} for UAE personal trainers.</p></div>
    ${cols.map((g) => `<nav class="foot-col" aria-label="${esc(g.label)}"><h2>${esc(g.label)}</h2><ul>${g.links.map((l) => `<li><a href="${href(l.href)}">${esc(l.label)}</a></li>`).join("")}</ul></nav>`).join("")}
  </div>
  <div class="foot-bottom">
    <p style="margin:0">© 2026 trainsyou · Company details and support email: [owner to supply]</p>
    <div class="foot-links"><a href="methodology.html">Every market figure sourced → Methodology</a><button type="button" data-open-consent>Analytics preferences</button></div>
  </div>
</div>
</footer>`;
}

/** Closing panel: Pace, ink text. { title, line, secondary: {label, href} } */
export function closingPanel(o = {}) {
  return `<section class="closing" aria-labelledby="closing-h">
<div class="container closing-inner">
  <div><h2 id="closing-h">${(o.title || "Your coaching. Beyond your hours.").split(/(?<=[.?!])\s+/).map((t) => `<span class="cl-s">${esc(t)}</span>`).join(" ")}</h2><p>${esc(o.line || "Guided setup. Nothing goes live until you publish.")}</p></div>
  <div><div class="cta-row">${primaryCta({ location: "closing" })}${o.secondary ? secondaryLink({ ...o.secondary, location: "closing", button: true }).replace('class="btn btn--secondary"', 'class="btn btn--secondary"') : ""}</div>${microLine()}</div>
</div>
</section>`;
}

function stickyCta() {
  return `<div class="sticky-cta" role="region" aria-label="Sign up">${primaryCta({ location: "sticky", block: true })}<small class="if-reg-open">Free to join</small><small class="if-reg-closed">Free to join · We'll tell you here when sign-ups reopen</small></div>`;
}
function consentBar() {
  return `<div class="consent" id="consent" role="region" aria-label="Analytics preferences" hidden>
<p>We use first-party analytics to see which pages help trainers. Nothing is shared with ad networks. <span class="muted">(Prototype: events log to the console.)</span></p>
<div class="row"><button class="btn btn--sm btn--secondary" type="button" data-consent="denied">Decline</button><button class="btn btn--sm" type="button" data-consent="granted">Accept</button></div>
</div>`;
}

function devPanel(path) {
  const sw = (key, label, sub) => `<div class="sw"><span id="sw-${key}">${esc(label)}${sub ? `<small>${esc(sub)}</small>` : ""}</span><button type="button" role="switch" aria-checked="false" aria-labelledby="sw-${key}" data-sw="${key}"></button></div>`;
  return `<button class="dev-btn" id="dev-btn" type="button" aria-expanded="false" aria-controls="dev" aria-label="Prototype controls">${icon("sliders")}<span class="dev-label">Prototype</span></button>
<div class="dev" id="dev" role="dialog" aria-label="Prototype controls">
  <h2>Concept B · Beyond Your Hours</h2>
  <p class="dev-sub">Prototype controls. Defaults match production today.</p>
  <div class="dev-sec"><p class="eyebrow eyebrow--muted">Product state</p>
    ${sw("payments", "Subscriber payments", "Payouts and paid bookings follow it. Live: off")}
    ${sw("registration", "Registration open", "Off shows the early-access labels. Live: on")}
    ${sw("publish", "Publish gate on", "Publishing waits for payments. Live: on")}
    ${sw("frontier", "Frontier model wording", "Off uses the fallback copy. Live: off")}
    ${sw("voice", "Voice add-on for subscribers", "Live: off")}
  </div>
  <div class="dev-sec"><p class="eyebrow eyebrow--muted">Owner decisions</p>
    ${sw("roll", "Digit roll on input", "Decision 6. Off: values crossfade")}
    ${sw("motion", "Reduced-motion variant", "Decision 5. Live: always")}
    ${sw("rtl", "RTL preview", "Subscriber-app vignette only")}
  </div>
  <div class="dev-sec dev-actions"><button class="btn btn--secondary" type="button" data-dev="replay">Replay hero</button><button class="btn btn--secondary" type="button" data-dev="consent">Reset consent</button><button class="btn btn--secondary" type="button" data-dev="reset">Live defaults</button><a class="btn btn--secondary" href="../">All concepts</a></div>
  <div class="dev-sec"><p class="eyebrow eyebrow--muted">All 42 pages</p><ul class="dev-pages">${registry.map((r) => `<li><a href="${r.file}"${cur(path, r.path)}>${esc(r.path === "/" ? "Home" : r.page.navLabel)}</a></li>`).join("")}</ul></div>
</div>`;
}

/**
 * Full HTML document.
 * entry: registry entry; out: { main, title, description, bodyClass, sticky, closing, kamran, styles, scripts, head }
 */
/** Adjacent source badges read "Source 1 →", "Source 2 →" instead of repeating "Source →". */
const numberSources = (html) => html.replace(/(?:<a class="src"[^>]*>Source<svg(?:(?!<\/a>)[\s\S])*<\/svg><\/a>\s*){2,}/g, (run) => { let i = 0; return run.replace(/>Source<svg/g, () => `>Source ${++i}<svg`); });

/**
 * Tables with 3+ columns stack on phones: every body cell gets its column
 * label (data-label) and its content in span.td-v, styled in site.css.
 */
const stackTables = (html) => html.replace(/<table class="table">([\s\S]*?)<\/table>/g, (m, inner) => {
  const head = inner.match(/<thead>([\s\S]*?)<\/thead>/);
  if (!head) return m;
  const labels = [...head[1].matchAll(/<th[^>]*>([\s\S]*?)<\/th>/g)].map((x) => x[1].replace(/<[^>]+>/g, "").trim());
  if (labels.length < 3) return m;
  const body = inner.replace(/<tbody>([\s\S]*?)<\/tbody>/, (b, rows) => "<tbody>" + rows.replace(/<tr>([\s\S]*?)<\/tr>/g, (row, cells) => {
    let i = 0;
    return "<tr>" + cells.replace(/<(td|th)(\s[^>]*)?>([\s\S]*?)<\/\1>/g, (c, tag, attrs = "", v) => {
      const label = labels[i++] || "";
      return tag === "th" ? `<th${attrs} data-label="${label}">${v}</th>` : `<td${attrs} data-label="${label}"><span class="td-v">${v}</span></td>`;
    }) + "</tr>";
  }) + "</tbody>");
  return `<table class="table table--stack">${body}</table>`;
});

/** Typographic apostrophes in visible text only (never inside tags, scripts or styles). */
const smartQuotes = (html) => html.split(/(<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>|<[^>]+>)/).map((part, i) => (i % 2 ? part : part.replace(/([A-Za-z])'([A-Za-z])/g, "$1’$2"))).join("");

export function renderPage(entry, out) {
  const p = entry.page;
  const title = out.title || (entry.path === "/" ? `trainsyou · ${p.title}` : `${p.title} · trainsyou`);
  const description = out.description || p.description || "";
  const sticky = out.sticky !== false;
  const group = entry.group;
  const css = ["site.css", `${group}.css`, ...(out.styles || [])];
  const js = ["site.js", "calc.js", `${group}.js`, ...(out.scripts || [])];
  const closing = out.closing === false ? "" : closingPanel(out.closing || {});
  return `<!doctype html>
<html lang="en" dir="ltr"${sticky ? ' class="has-sticky"' : ""}>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>${esc(title)}</title>
<meta name="description" content="${esc(description)}">
<meta name="robots" content="noindex, nofollow">
<meta name="color-scheme" content="light">
<meta name="theme-color" content="#FFFFFF">
<link rel="icon" href="assets/favicon.svg" type="image/svg+xml">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link rel="stylesheet" href="${FONTS}">
${css.map((f) => `<link rel="stylesheet" href="assets/${f}">`).join("\n")}
<script src="assets/boot.js"></script>
${js.map((f) => `<script src="assets/${f}" defer></script>`).join("\n")}
<noscript><style>.acc-panel{grid-template-rows:1fr;visibility:visible}.sticky-cta{display:none!important}</style></noscript>
${out.head || ""}
</head>
${smartQuotes(`<body data-page="${esc(entry.path)}" data-kind="${esc(p.kind || "")}"${out.bodyClass ? ` class="${esc(out.bodyClass)}"` : ""}>
<a class="skip-link" href="#main">Skip to content</a>
${header(entry.path)}
<main id="main">
${stackTables(numberSources(out.main))}
</main>
${closing}
${footer()}
${sticky ? stickyCta() : ""}
${out.kamran ? `<button type="button" class="kamran kamran--float" data-kamran="float"><span class="k-dot">${icon("mic")}</span>Talk to Kamran (AI voice)</button>` : ""}
${consentBar()}
${devPanel(entry.path)}
</body>`)}
</html>
`;
}
